 FOREACH name IN ARRAY ARRAY['admin_sessions','analytics_events','arena_customer_reward_adjustments','arena_customer_reward_draws','arena_customer_reward_grants','arena_customer_reward_seasons','arena_customer_reward_week_rolls','arena_customer_reward_weeks','arena_feedback','asset_refs','audit_logs','blog_comments','blog_posts','blog_ratings','chanvrier_achievement_catalog','checkout_attempts','cms_pages','contest_badges','contest_beta_testers','contest_entries','contest_notebook_reset_archive','contest_profile_badges','contest_profiles','contest_review_aroma_tags','contest_review_scores','contest_review_terpene_guesses','contest_review_votes','contest_reviews','contest_reward_unlocks','contest_rewards','contest_seasons','contest_tester_points','invoice_counter','invoices','kq_arena_tasting_transition_credits','kq_bank_markets','kq_contest_bundle_order_snapshots','kq_contest_bundle_reward_grants','kq_contest_bundle_settings','kq_crypto_quotes','kq_crypto_refresh_state','kq_equipment_catalog','kq_heritage_card_definitions','kq_heritage_draws','kq_heritage_effect_catalog','kq_heritage_fragment_ledger','kq_heritage_fragment_wallets','kq_heritage_player_state','kq_notebook_flower_reward_grants','kq_notebook_flower_reward_packs','kq_notebook_reward_grants','kq_notebook_reward_rules','kq_order_cash_reward_grants','kq_order_cash_reward_settings','kq_pioneer_pack_grants','kq_producer_completion_grants','kq_producer_heritage_reward_grants','kq_producer_purchase_buddie_grants','kq_producer_quantity_bonus_grants','kq_producer_reward_campaigns','kq_producer_reward_entries','kq_school_catalog','kq_school_question_feedback','kq_school_tournament_actors','kq_season_reward_grants','kq_season_reward_rules','kq_seasons','kq_stock_instruments','kq_stock_quotes','kq_support_card_rules','kq_support_points_purchases','lottery_album_cards','lottery_album_page_slots','lottery_album_pages','lottery_bonus_definitions','lottery_bonus_instances','lottery_bonus_options','lottery_card_collectio